def prefix_search(sorted_words, prefix, top_k=None):
    if not prefix:
        return sorted_words[:top_k] if top_k else list(sorted_words)
    lo = bisect.bisect_left(sorted_words, prefix)
    hi_key = prefix[:-1] + chr(ord(prefix[-1]) + 1)
    hi = bisect.bisect_left(sorted_words, hi_key)
    result = sorted_words[lo:hi]
    return result[:top_k] if top_k else result

