def fuzzy_search(buckets, query, max_distance, top_n=None):
    qlen = len(query)
    results = []
    for length in range(max(0, qlen - max_distance), qlen + max_distance + 1):
        for w in buckets.get(length, []):
            d = edit_distance(query, w)
            if d <= max_distance:
                results.append((d, w))
    results.sort()
    return results[:top_n] if top_n else results

import hashlib

def hash_record(record, fields):
    parts = []
    for f in fields:
        val = record.get(f, '')
        val = '' if val is None else str(val)
        parts.append(val.strip().lower())
    joined = '|'.join(parts)
    return hashlib.sha256(joined.encode('utf-8')).hexdigest()

def find_exact_duplicates(records, fields):
    groups = {}
    for i, r in enumerate(records):
        h = hash_record(r, fields)
        groups.setdefault(h, []).append(i)
    return {h: idxs for h, idxs in groups.items() if len(idxs) > 1}

import math
from collections import Counter

def build_tfidf(docs):
    N = len(docs)
    tokenized = [ [t.lower() for t in d.split() if t.isalnum()] for d in docs ]
    df = Counter()
    for tokens in tokenized:
        for term in set(tokens):
            df[term] += 1
    idf = {term: math.log(N / df[term]) for term in df} if N > 0 else {}
    tfidf = {}
    for doc_id, tokens in enumerate(tokenized):
        tf = Counter(tokens)
        length = len(tokens) if tokens else 1
        for term, count in tf.items():
            weight = (count / length) * idf.get(term, 0)
            tfidf.setdefault(term, {})[doc_id] = weight
    return {'tfidf': tfidf, 'N': N}

def rank(tfidf_data, query, top_k, min_score=None):
    tfidf = tfidf_data['tfidf']
    terms = [t.lower() for t in query.split() if t]
    scores = {}
    for term in terms:
        for doc_id, w in tfidf.get(term, {}).items():
            scores[doc_id] = scores.get(doc_id, 0.0) + w
    if min_score is not None:
        scores = {d: s for d, s in scores.items() if s >= min_score}
    ranked = sorted(scores.items(), key=lambda x: (-x[1], x[0]))
    return ranked[:top_k]

