def _kmp_table(pattern):
    table = [0] * len(pattern)
    k = 0
    for i in range(1, len(pattern)):
        while k > 0 and pattern[i] != pattern[k]:
            k = table[k-1]
        if pattern[i] == pattern[k]:
            k += 1
        table[i] = k
    return table

def _kmp_search(text, pattern, table):
    positions = []
    k = 0
    for i, ch in enumerate(text):
        while k > 0 and ch != pattern[k]:
            k = table[k-1]
        if ch == pattern[k]:
            k += 1
        if k == len(pattern):
            positions.append(i - len(pattern) + 1)
            k = table[k-1]
    return positions

def search_substring(docs, pattern, case_sensitive=True):
    if not pattern:
        return {}
    p = pattern if case_sensitive else pattern.lower()
    table = _kmp_table(p)
    result = {}
    for doc_id, text in enumerate(docs):
        t = text if case_sensitive else text.lower()
        positions = _kmp_search(t, p, table)
        if positions:
            result[doc_id] = positions
    return result

