def evaluate(index, total_docs, expr, case_insensitive=True):
    tokens = expr.replace('(', ' ( ').replace(')', ' ) ').split()
    pos = [0]
    all_docs = set(range(total_docs))

    def term_set(t):
        key = t.lower() if case_insensitive else t
        return set(index.get(key, []))

    def parse_or():
        left = parse_and()
        while pos[0] < len(tokens) and tokens[pos[0]] == 'OR':
            pos[0] += 1
            left = left | parse_and()
        return left

    def parse_and():
        left = parse_not()
        while pos[0] < len(tokens) and tokens[pos[0]] == 'AND':
            pos[0] += 1
            left = left & parse_not()
        return left

    def parse_not():
        if pos[0] < len(tokens) and tokens[pos[0]] == 'NOT':
            pos[0] += 1
            return all_docs - parse_atom()
        return parse_atom()

    def parse_atom():
        if tokens[pos[0]] == '(':
            pos[0] += 1
            result = parse_or()
            pos[0] += 1  # consume ')'
            return result
        t = tokens[pos[0]]
        pos[0] += 1
        return term_set(t)

    result = parse_or()
    return sorted(result)

class PhoneHashTable:
    def __init__(self, num_buckets):
        self.num_buckets = num_buckets
        self.buckets = [[] for _ in range(num_buckets)]

    def _hash(self, phone_number):
        return sum(ord(c) for c in phone_number) % self.num_buckets

    def insert(self, phone_number, name):
        idx = self._hash(phone_number)
        chain = self.buckets[idx]
        for i, (pn, nm) in enumerate(chain):
            if pn == phone_number:
                chain[i] = (phone_number, name)
                return
        chain.append((phone_number, name))

    def lookup(self, phone_number):
        idx = self._hash(phone_number)
        for pn, nm in self.buckets[idx]:
            if pn == phone_number:
                return nm
        return None

    def delete(self, phone_number):
        idx = self._hash(phone_number)
        chain = self.buckets[idx]
        for i, (pn, nm) in enumerate(chain):
            if pn == phone_number:
                del chain[i]
                return True
        return False

def ngrams(s, n):
    s = s.lower()
    if len(s) < n:
        return set()
    return set(s[i:i+n] for i in range(len(s) - n + 1))

def build_ngram_index(words, n):
    index = {}
    for i, w in enumerate(words):
        for g in ngrams(w, n):
            index.setdefault(g, set()).add(i)
    return index

def search(words, ngram_index, query, n, threshold, top_k=None):
    q_grams = ngrams(query, n)
    if not q_grams:
        return []
    candidates = set()
    for g in q_grams:
        candidates.update(ngram_index.get(g, set()))
    results = []
    for idx in candidates:
        w_grams = ngrams(words[idx], n)
        union = q_grams | w_grams
        inter = q_grams & w_grams
        sim = len(inter) / len(union) if union else 0.0
        if sim >= threshold:
            results.append((idx, sim))
    results.sort(key=lambda x: (-x[1], x[0]))
    return results[:top_k] if top_k else results

def search_logs(lines, pattern, count_only=False):
