def search_with_context(lines, pattern, before, after):
    matches = search_logs(lines, pattern)
    included = set()
    for m in matches:
        start = max(0, m - before)
        end = min(len(lines) - 1, m + after)
        for i in range(start, end + 1):
            included.add(i)
    return [(i, lines[i]) for i in sorted(included)]

def shingles(text, k):
