def find_near_duplicates(docs, shingle_index, k, threshold):
    doc_shingles = [shingles(d, k) for d in docs]
    candidate_pairs = set()
    for s, doc_ids in shingle_index.items():
        ids = sorted(doc_ids)
        for a in range(len(ids)):
            for b in range(a + 1, len(ids)):
                candidate_pairs.add((ids[a], ids[b]))
    results = []
    for i, j in candidate_pairs:
        si, sj = doc_shingles[i], doc_shingles[j]
        union = si | sj
        sim = len(si & sj) / len(union) if union else 0.0
        if sim >= threshold:
            results.append((i, j, sim))
    results.sort(key=lambda x: (-x[2], x[0], x[1]))
    return results

def edit_distance(a, b):
