            prev = temp
    return dp[n]

class BKTree:
    def __init__(self):
        self.root = None

    def insert(self, word):
        if self.root is None:
            self.root = {'word': word, 'children': {}}
            return
        node = self.root
        while True:
            d = edit_distance(word, node['word'])
            if d == 0:
                return
            if d in node['children']:
                node = node['children'][d]
            else:
                node['children'][d] = {'word': word, 'children': {}}
                return

    def search(self, query, max_distance):
        if self.root is None:
            return []
        results = []
        stack = [self.root]
        while stack:
            node = stack.pop()
            d = edit_distance(query, node['word'])
            if d <= max_distance:
                results.append((node['word'], d))
            for edge_d, child in node['children'].items():
                if abs(edge_d - d) <= max_distance:
                    stack.append(child)
        results.sort(key=lambda x: (x[1], x[0]))
        return results

    def best_match(self, query):
        all_matches = self.search(query, max_distance=10**9)
        return all_matches[0] if all_matches else None

