def top_k_heap(scored, k, min_score=None):
    if k <= 0:
        return []
    candidates = scored if min_score is None else [s for s in scored if s[1] >= min_score]
    if k >= len(candidates):
        result = list(candidates)
    else:
        heap = []
        for doc_id, score in candidates:
            entry = (score, -doc_id)
            if len(heap) < k:
                heapq.heappush(heap, entry)
            elif entry > heap[0]:
                heapq.heapreplace(heap, entry)
        result = [(-neg_id, score) for score, neg_id in heap]
    result.sort(key=lambda x: (-x[1], x[0]))
    return result

def matches_wildcard(name, pattern, case_sensitive=True):
    if not case_sensitive:
        name, pattern = name.lower(), pattern.lower()
    m, n = len(name), len(pattern)
    dp = [[False]*(n+1) for _ in range(m+1)]
    dp[0][0] = True
    for j in range(1, n+1):
        if pattern[j-1] == '*':
            dp[0][j] = dp[0][j-1]
    for i in range(1, m+1):
        for j in range(1, n+1):
            if pattern[j-1] == '*':
                dp[i][j] = dp[i-1][j] or dp[i][j-1]
            elif pattern[j-1] == '?' or pattern[j-1] == name[i-1]:
                dp[i][j] = dp[i-1][j-1]
    return dp[m][n]

def search_wildcard(names, pattern, case_sensitive=True):
    return [i for i, nm in enumerate(names) if matches_wildcard(nm, pattern, case_sensitive)]

