        candidates = set(r['id'] for r in rows)
    if in_stock_only:
        stock_ids = set(r['id'] for r in rows if r.get('in_stock'))
        candidates = candidates & stock_ids
    result = sorted(candidates)
    if sort_by in ('price_asc', 'price_desc'):
        price_map = {r['id']: r.get('price', 0) for r in rows}
        result.sort(key=lambda i: price_map[i], reverse=(sort_by == 'price_desc'))
    return result

import bisect

def build_frequency_index(query_log):
    freq = {}
    for q in query_log:
        norm = q.strip().lower()
        freq[norm] = freq.get(norm, 0) + 1
    return freq

def build_prefix_structure(freq_index):
    return sorted(freq_index.keys())

def suggest(freq_index, sorted_queries, prefix, top_k):
    p = prefix.lower()
    if not p:
        candidates = sorted_queries
    else:
        lo = bisect.bisect_left(sorted_queries, p)
        hi_key = p[:-1] + chr(ord(p[-1]) + 1)
        hi = bisect.bisect_left(sorted_queries, hi_key)
        candidates = sorted_queries[lo:hi]
    scored = [(freq_index[q], q) for q in candidates]
    scored.sort(key=lambda x: (-x[0], x[1]))
    return [(q, f) for f, q in scored[:top_k]]

def update_frequency(freq_index, sorted_queries, new_query):
    norm = new_query.strip().lower()
    if norm in freq_index:
        freq_index[norm] += 1
    else:
        freq_index[norm] = 1
        bisect.insort(sorted_queries, norm)

import heapq

def build_shards(records, num_shards):
    shards = [dict() for _ in range(num_shards)]
    for r in records:
        shard_id = hash(r['id']) % num_shards
        idx = shards[shard_id]
        for tag in r.get('tags', []):
            idx.setdefault(tag, []).append(r['id'])
    for idx in shards:
        for tag in idx:
            idx[tag].sort()
    return shards

def query_shard(shard_index, tag):
    return shard_index.get(tag, [])

def query_all_shards(shards, tag):
    sorted_lists = [query_shard(s, tag) for s in shards]
    merged = heapq.merge(*sorted_lists)
    result = []
    prev = object()
    for x in merged:
        if x != prev:
            result.append(x)
            prev = x
    return result

def query_all_shards_multi_tag(shards, tags, mode='AND'):
    tag_results = [set(query_all_shards(shards, t)) for t in tags]
    if not tag_results:
        return []
    if mode == 'AND':
        combined = tag_results[0]
        for s in tag_results[1:]:
            combined = combined & s
    else:
        combined = set()
        for s in tag_results:
            combined |= s
    return sorted(combined)
